mapper.select:
SELECT id, name, price, stock, category_id, detail
FROM pms_product
WHERE is_deleted = 0
AND category_id IN (
    SELECT id FROM pms_category WHERE parent_id = #{categoryId} AND is_deleted = 0
    UNION SELECT #{categoryId}
)
ORDER BY create_time DESC
LIMIT #{limit}

SELECT id, name, price, stock, category_id, detail, status
FROM pms_product
WHERE is_deleted = 0

    AND name LIKE CONCAT('%', #{name}, '%')


    AND status = #{status}


    AND category_id IN (
        SELECT id FROM pms_category WHERE parent_id = #{categoryId} AND is_deleted = 0
        UNION SELECT #{categoryId}
    )

ORDER BY create_time DESC
